 where r.id = ah.entity_id and ah.entity_type = 'restaurant' and ah.award_type = 'michelin_stars'
   and ah.guide_year = 2026 and ah.is_current and ah.announced_on is null
   and r.restaurant_code = any(array['rest_0175', 'rest_0176', 'rest_0177', 'rest_0178', 'rest_0179', 'rest_0181', 'rest_0182', 'rest_0184', 'rest_0185', 'rest_0186', 'rest_0187', 'rest_0188', 'rest_0189', 'rest_0190', 'rest_0191', 'rest_0192', 'rest_0193', 'rest_0194', 'rest_0195', 'rest_0196', 'rest_0197', 'rest_0198', 'rest_0199', 'rest_0200', 'rest_0201', 'rest_0202', 'rest_0203', 'rest_0204', 'rest_0205', 'rest_0206', 'rest_0207', 'rest_0208', 'rest_0209', 'rest_0210', 'rest_0211', 'rest_0212', 'rest_0213', 'rest_0214', 'rest_0215', 'rest_0216', 'rest_0217', 'rest_0218', 'rest_0219', 'rest_0220', 'rest_0221', 'rest_0222', 'rest_0223', 'rest_0224', 'rest_0225', 'rest_0226', 'rest_0227', 'rest_0228', 'rest_0229', 'rest_0230', 'rest_0231', 'rest_0232', 'rest_0233', 'rest_1373']);

-- DE 2. 2026 changes (promotions/demotions) and losses: close the current row, open 2026
create temp table _chg_de (code text primary key, stars smallint) on commit drop;
update public.award_history ah set is_current = false
  from public.restaurants r, _chg_de c
 where r.id = ah.entity_id and r.restaurant_code = c.code
   and ah.entity_type = 'restaurant' and ah.award_type = 'michelin_stars' and ah.is_current;
select 'restaurant', r.id, 2026, 'michelin_stars', c.stars, true, date '2026-06-23'
  from public.restaurants r join _chg_de c on c.code = r.restaurant_code;
update public.restaurants r set michelin_stars = c.stars, updated_at = now()
  from _chg_de c where r.restaurant_code = c.code;

-- DE 4. starred restaurants missing from the catalogue
create temp table _new_de (code text, name text, stars smallint, city text, address text, lon float8, lat float8,
                         michelin_url text, website_url text, phone text, property_name text, place_id text) on commit drop;
do $$
declare bad text;
begin
  select string_agg(x.code, ', ') into bad from _new_de x join public.restaurants r on r.restaurant_code = x.code;
  if bad is not null then raise exception 'DE: codes no longer free: %', bad; end if;
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_de x
   where (select count(*) from public.cities c where c.country_code = 'DE' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'DE: city does not resolve to exactly one row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_de x join public.restaurants r on r.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'DE: already present (michelin_url): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_de x join public.restaurants r on r.google_place_id = x.place_id;
  if bad is not null then raise exception 'DE: Place ID already used: %', bad; end if;
end $$;
                                address, location, michelin_url, website_url, phone, property_name, google_place_id)
select x.code, x.name, x.stars, 'michelin_star',
       (select c.id from public.cities c where c.country_code = 'DE' and c.name = x.city), 'DE',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone, x.property_name, x.place_id
  from _new_de x;
select 'restaurant', r.id, 2026, 'michelin_stars', x.stars, true, date '2026-06-23'
  from _new_de x join public.restaurants r on r.restaurant_code = x.code;

-- DE 5. existing rows, fill-only (never overwrites)
create temp table _fill_de (code text primary key, michelin_url text, phone text, website_url text, place_id text, property_name text) on commit drop;
do $$
declare bad text;
begin
  select string_agg(f.code, ', ') into bad from _fill_de f join public.restaurants r on r.michelin_url = f.michelin_url and r.restaurant_code <> f.code;
  if bad is not null then raise exception 'DE: michelin_url used by another row: %', bad; end if;
  select string_agg(f.code, ', ') into bad from _fill_de f join public.restaurants r on r.google_place_id = f.place_id and r.restaurant_code <> f.code;
  if bad is not null then raise exception 'DE: Place ID used by another row: %', bad; end if;
end $$;
update public.restaurants r set michelin_url = f.michelin_url, updated_at = now() from _fill_de f where r.restaurant_code = f.code and f.michelin_url is not null and r.michelin_url is null;
update public.restaurants r set phone = f.phone, updated_at = now() from _fill_de f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill_de f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
update public.restaurants r set google_place_id = f.place_id, updated_at = now() from _fill_de f where r.restaurant_code = f.code and f.place_id is not null and r.google_place_id is null;
update public.restaurants r set property_name = f.property_name, updated_at = now() from _fill_de f where r.restaurant_code = f.code and f.property_name is not null and r.property_name is null
   and not exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);

-- DE 6. links to hotels in `hotels`
create temp table _links_de (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_de l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- DE post-conditions: MICHELIN's live 2026 listing
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'DE' and michelin_stars = 3;
  if n <> 12 then raise exception 'DE: expected 12 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'DE' and michelin_stars = 2;
  if n <> 48 then raise exception 'DE: expected 48 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'DE' and michelin_stars = 1;
  if n <> 278 then raise exception 'DE: expected 278 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'DE'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception 'DE: % restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'DE' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception 'DE: % restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'DE' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception 'DE: % restaurants have both a hotel link and a property_name', n; end if;
end $$;

